{
  "title": "CSCI-605: Advanced Object-Oriented Programming Concepts",
  "learningObjectives": [
    "Define and distinguish between event-driven programming, design patterns, and distributed/concurrent programming paradigms.",
    "Apply the five essential characteristics of cloud computing to evaluate scalable service architectures.",
    "Explain how Raft consensus mechanisms ensure log safety and leader election in distributed systems."
  ],
  "beats": [
    {
      "title": "Course Scope and Prerequisites",
      "claim": "CSCI-605 is a graduate bridge course restricted to COMPSCI-MS students and requires permission from the CS Undergraduate Program Coordinator for undergraduate enrollment.",
      "example": "A graduate student in the COMPSCI-MS program registers for the course without needing additional approval.",
      "visualDirection": "Display a course eligibility matrix highlighting the COMPSCI-MS restriction and permission requirement.",
      "sourceIds": ["rit-csci-605"]
    },
    {
      "title": "Advanced OOP Focus Areas",
      "claim": "The curriculum centers on identifying and implementing advanced object-oriented programming concepts within specific problem contexts.",
      "example": "Students analyze a real-world application requiring modular design to isolate complex business logic.",
      "visualDirection": "Show a flowchart mapping core topics: event-driven programming, design patterns, distributed/concurrent programming, and application implementation.",
      "sourceIds": ["rit-csci-605"]
    },
    {
      "title": "Event-Driven Programming Fundamentals",
      "claim": "Event-driven programming structures applications around asynchronous event handling rather than linear control flow.",
      "example": "A UI component automatically updates when a network request completes without polling.",
      "visualDirection": "Illustrate a publisher-subscriber diagram showing decoupled event emission and subscription.",
      "sourceIds": ["rit-csci-605"]
    },
    {
      "title": "Design Patterns Overview",
      "claim": "Design patterns provide reusable solutions to common software design problems, improving code maintainability.",
      "example": "Implementing a singleton pattern to manage a single database connection pool across modules.",
      "visualDirection": "Display a before-and-after code snippet comparing rigid inheritance to a flexible pattern implementation.",
      "sourceIds": ["rit-csci-605"]
    },
    {
      "title": "Distributed and Concurrent Programming",
      "claim": "Distributed and concurrent programming enable systems to coordinate across multiple nodes or threads efficiently.",
      "example": "Splitting a data processing workload across multiple CPU cores to reduce execution time.",
      "visualDirection": "Render a parallel processing diagram showing thread/task distribution across cores.",
      "sourceIds": ["rit-csci-605"]
    },
    {
      "title": "Cloud Computing Characteristics",
      "claim": "NIST defines cloud computing with five essential characteristics: on-demand self-service, broad network access, resource pooling, rapid elasticity, and measured service.",
      "example": "A startup dynamically scales compute resources during a traffic spike without manual intervention.",
      "visualDirection": "List the five NIST characteristics with brief definitions and a scaling graph overlay.",
      "sourceIds": ["nist-cloud"]
    },
    {
      "title": "Cloud Deployment Models",
      "claim": "NIST identifies private, community, public, and hybrid deployment models, each defining distinct trust boundaries and responsibility allocation.",
      "example": "A financial institution uses a hybrid model to keep sensitive data on-premise while using public cloud for analytics.",
      "visualDirection": "Show a Venn diagram comparing private, community, public, and hybrid deployment boundaries.",
      "sourceIds": ["nist-cloud"]
    },
    {
      "title": "Raft Consensus Leader Election",
      "claim": "Raft decomposes consensus into leader election, log replication, and safety, with terms acting as logical clocks to identify stale information.",
      "example": "A server becomes leader after receiving votes from a majority during an election timeout period.",
      "visualDirection": "Animate state transitions (follower -> candidate -> leader) with term counters and vote requests.",
      "sourceIds": ["raft-paper"]
    },
    {
      "title": "Raft Log Replication and Safety",
      "claim": "A leader appends client commands to its log and sends entries to followers, with an entry becoming committed after the required majority condition is satisfied.",
      "example": "A replicated log ensures all nodes store identical command sequences before acknowledging client requests.",
      "visualDirection": "Display a log replication sequence showing entry propagation and majority acknowledgment.",
      "sourceIds": ["raft-paper"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Students must evaluate system designs using durable concepts and problem-solving methods, ensuring assignments require both solution analysis and code implementation.",
      "example": "A student reviews a distributed system architecture, identifies event-driven components, and implements a consensus module in code.",
      "visualDirection": "Provide a checklist template covering: paradigm identification, pattern selection, concurrency/cloud alignment, and code validation.",
      "sourceIds": ["rit-csci-605"]
    }
  ]
}
